128:     });
129: 
130:     // NOTE: Mode Button & Change Mode Modal
131:     ModalCon mode_con;
132:     auto change_buttons = Container::Vertical({});
133:     for (const auto& mode : ::modes) {
134:         auto change_fn = [mode, &mode_con, &tab_con]() {
135:             if (mode == "compare") {
136:                 const std::string source = app_state.searchengine.get_loaded_text();
137:                 app_state.compare_metrics = make_compare_metrics(source, app_state.input);
138:                 tab_con.change(1);
139:                 mode_con.close();
140:             } else {
141:                 app_state.switch_mode(mode);
142:                 tab_con.change(0);
143:                 mode_con.close();
144:             }
145:         };
146:         change_buttons->Add(Button(mode, change_fn));
147:     }
148:     auto mode_fn = [&mode_con]() { mode_con.open(); };
149:     auto mode_button = Button("Mode", mode_fn);
150:     auto mode_modal = Renderer(change_buttons, [&] {
151:         return vbox({text("Choose Mode") | center, separator(), change_buttons->Render()}) | border;
152:     });
153: 
154:     // NOTE: Menu & Detail
155:     MenuCon menu_con{};
156:     auto menu = Menu(&menu_con.entry, &menu_con.idx);
157:     Box menu_box;
158:     Box detail_box;
159:     Box body_box;
160: 
161:     // NOTE: search button
162:     auto search = [&menu_con, &tab_con, &detail_scroll] {
163:         if (tab_con.idx == 1) {
164:             const std::string source = app_state.searchengine.get_loaded_text();
165:             app_state.compare_metrics = make_compare_metrics(source, app_state.input);
166:             return;
167:         }
168: 
169:         SearchRequest request{
170:             .mode = app_state.mode,
171:             .query = app_state.input,
172:             .near_distance = parse_near_distance(app_state.near_distance),
173:         };
174:         app_state.search_res = app_state.searchengine.search_with_context(request);
175:         menu_con.entry = app_state.search_res | std::views::transform([](const Index& ele) {
176:             return std::format("{}", ele);
177:         }) | std::ranges::to<std::vector<std::string>>();
178:         menu_con.idx = 0;
179:         detail_scroll = 0;
180:     };
181:     auto search_button = Button("Search", search);
182: 
183:     // NOTE: Input
184:     auto get_input = [&search](std::string& content) {
185:         InputOption option;
186:         option.multiline = false;
187:         option.on_enter = search;
188:         return Input(&content, option);
189:     };
190:     auto search_input = get_input(app_state.input);
191:     auto distance_input = get_input(app_state.near_distance);
192:     auto distance_input_con = Renderer(distance_input, [&] {
193:         return hbox({text(" Distance:"), distance_input->Render()});
194:     }) | Maybe([] { return app_state.mode == SearchMode::Near; });
195: 
196:     auto top_bar_eles = Container::Horizontal(
197:         {add_button, mode_button, search_input, distance_input_con, search_button});
198:     auto top_bar = Renderer(top_bar_eles, [&]() {
199:         return hbox(
200:             {add_button->Render(),
201:                 mode_button->Render(),
202:                 search_input->Render(),
203:                 distance_input_con->Render(),
204:                 search_button->Render()});
205:     });
206: 
207:     // NOTE: Body
208:     auto body_eles = Container::Horizontal({menu});
209:     auto body = Renderer(body_eles, [&] {
210:         if (tab_con.idx == 1) {
211:             return compare_pane(app_state.compare_metrics);
212:         }
213: 
214:         Element detail = emptyElement();
215:         if (!app_state.search_res.empty() && menu_con.idx >= 0 &&
216:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size()) {
217:             detail = detail_pane(app_state.get_context(menu_con.idx)) |
218:                      focusPosition(0, detail_scroll) | vscroll_indicator | yframe;
219:         }
220:         return hbox(
221:                    {menu->Render() | vscroll_indicator | frame | flex | reflect(menu_box),
222:                        separator(),
223:                        detail | flex | reflect(detail_box)}) |
224:                reflect(body_box);
225:     });
226: 
227:     // NOTE: State Bar
228:     auto state_bar = Renderer([&] {
229:         return hbox(
230:             {text(std::format("Loaded Book: {}", app_state.loaded_books.size())),
231:                 emptyElement() | flex,
232:                 text(std::format("Search Count:{}", app_state.search_res.size())),
233:                 emptyElement() | flex,
234:                 text(std::format("Mode:{}", app_state.mode))});
235:     });
236: 
237:     auto main_eles = Container::Vertical({top_bar, body, state_bar});
238:     auto main_renderer = Renderer(main_eles, [&] {
239:         return vbox(
240:             {top_bar->Render() | borderEmpty,
241:                 body->Render() | flex | borderRounded,
242:                 state_bar->Render() | borderEmpty});
243:     });
244: 
245:     main_renderer |= Modal(add_modal, &add_con.is_open);
246:     main_renderer |= Modal(mode_modal, &mode_con.is_open);
247:     main_renderer |= CatchEvent([&](Event event) {
248:         if (event == Event::Escape && add_con.is_open) {
249:             add_con.close();
250:             return true;
251:         }
252:         if (event == Event::Escape && mode_con.is_open) {
253:             mode_con.close();
254:             return true;
255:         }
256: 
257:         const bool can_scroll_detail =
258:             !add_con.is_open && !mode_con.is_open && tab_con.idx == 0 &&
259:             !app_state.search_res.empty() && menu_con.idx >= 0 &&
260:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size();
261:         if (!can_scroll_detail) {
262:             return false;
263:         }
264: 
265:         auto scroll_detail = [&](int delta) {
266:             detail_scroll = std::max(0, detail_scroll + delta);
267:             return true;
268:         };
269:         auto is_in_box = [](const Box& box, int x, int y) {
270:             return x >= box.x_min && x <= box.x_max && y >= box.y_min && y <= box.y_max;
271:         };
272:         auto is_in_detail_area = [&](int x, int y) {
273:             if (is_in_box(menu_box, x, y)) {
274:                 return false;
275:             }
276:             if (is_in_box(detail_box, x, y)) {
277:                 return true;
278:             }
279:             return is_in_box(body_box, x, y) && x > menu_box.x_max;
280:         };
281: 
282:         if (event == Event::PageUp) {
283:             return scroll_detail(-8);
284:         }
285:         if (event == Event::PageDown) {
286:             return scroll_detail(8);
287:         }
288:         if (event == Event::ArrowUpCtrl) {
289:             return scroll_detail(-1);
290:         }
291:         if (event == Event::ArrowDownCtrl) {
292:             return scroll_detail(1);
293:         }
294:         if (event.is_mouse() &&
295:             (event.mouse().button == Mouse::WheelUp || event.mouse().button == Mouse::WheelDown)) {
296:             if (!is_in_detail_area(event.mouse().x, event.mouse().y)) {
297:                 return false;
298:             }
299:             return scroll_detail(event.mouse().button == Mouse::WheelUp ? -3 : 3);
300:         }
301:         return false;
302:     });
303: 
304:     screen.Loop(main_renderer);
305: }

