28: std::string get_filename(std::string_view path) {
29:     const std::size_t pos = path.find_last_of("/\\");
30: 
31:     if (pos == std::string_view::npos) {
32:         return std::string(path);
33:     }
34: 
35:     return std::string(path.substr(pos + 1));
36: }
