38: size_t parse_near_distance(std::string_view value) {
39:     size_t distance = default_near_distance;
40:     const char* begin = value.data();
41:     const char* end = begin + value.size();
42:     const auto [ptr, ec] = std::from_chars(begin, end, distance);
43: 
44:     if (ec != std::errc{} || ptr != end) {
45:         return default_near_distance;
46:     }
47: 
48:     return distance;
49: }
