65: ftxui::Element compare_pane(const AlgoResults& metrics) {
66:     using namespace ftxui;
67: 
68:     const auto fastest = std::ranges::min_element(metrics, {}, &AlgoResult::use_time_ms);
69:     const auto fewest_comparisons =
70:         std::ranges::min_element(metrics, {}, &AlgoResult::compare_count);
71:     const auto max_comparisons =
72:         std::ranges::max(metrics | std::views::transform(&AlgoResult::compare_count));
73:     const auto max_time = std::ranges::max(metrics | std::views::transform(&AlgoResult::use_time_ms));
74: 
75:     auto summary = window(
76:         text(" Compare Summary ") | bold,
77:         vbox({text(std::format("Fastest algorithm: {} ({} ms)",
78:                   fastest->name,
79:                   fastest->use_time_ms)),
80:             text(std::format("Fewest comparisons: {} ({})",
81:                 fewest_comparisons->name,
82:                 fewest_comparisons->compare_count))}));
83: 
84:     Elements table_rows{text("Algorithm        Matches    Comparisons      Time(ms)") | bold,
85:         separator()};
86:     for (const AlgoResult& metric : metrics) {
87:         table_rows.push_back(text(std::format("{:<14} {:>8} {:>16} {:>13}",
88:             metric.name,
89:             metric.match_count,
90:             metric.compare_count,
91:             metric.use_time_ms)));
92:     }
93:     auto metrics_table = window(text(" Metrics Table ") | bold, vbox(std::move(table_rows)));
94: 
95:     auto bar = [](long long value, long long max_value) {
96:         constexpr int bar_width = 24;
97:         const int filled = max_value == 0 ? 0 : static_cast<int>((value * bar_width) / max_value);
98:         return std::format("{}{}", std::string(filled, '#'), std::string(bar_width - filled, '-'));
99:     };
100: 
101:     Elements visual_rows;
102:     for (const AlgoResult& metric : metrics) {
103:         visual_rows.push_back(text(metric.name) | bold);
104:         visual_rows.push_back(text(std::format("  Comparisons [{}] {}",
105:             bar(static_cast<long long>(metric.compare_count), static_cast<long long>(max_comparisons)),
106:             metric.compare_count)));
107:         visual_rows.push_back(text(std::format("  Time(ms)    [{}] {}",
108:             bar(metric.use_time_ms, max_time),
109:             metric.use_time_ms)));
110:     }
111:     auto visual_comparison =
112:         window(text(" Visual Comparison ") | bold, vbox(std::move(visual_rows)));
113: 
114:     return vbox({summary, separator(), metrics_table, separator(), visual_comparison}) | frame | flex;
115: }
