72: size_t parse_near_distance(std::string_view value) {
73:     size_t distance = default_near_distance;
74:     const char* begin = value.data();
75:     const char* end = begin + value.size();
76:     const auto [ptr, ec] = std::from_chars(begin, end, distance);
77: 
78:     if (ec != std::errc{} || ptr != end) {
79:         return default_near_distance;
80:     }
81: 
82:     return distance;
83: }
