113: ftxui::Element compare_pane(const AlgoResults& metrics) {
114:     using namespace ftxui;
115: 
116:     const auto fastest = std::ranges::min_element(metrics, {}, &AlgoResult::use_time_ms);
117:     const auto fewest_comparisons =
118:         std::ranges::min_element(metrics, {}, &AlgoResult::compare_count);
119:     const auto max_comparisons =
120:         std::ranges::max(metrics | std::views::transform(&AlgoResult::compare_count));
121:     const auto max_time =
122:         std::ranges::max(metrics | std::views::transform(&AlgoResult::use_time_ms));
123: 
124:     auto summary = window(text(" Compare Summary ") | heading_text(),
125:         vbox(
126:             {text(
127:                  std::format("Fastest algorithm: {} ({} ms)", fastest->name, fastest->use_time_ms)),
128:                 text(std::format("Fewest comparisons: {} ({})",
129:                     fewest_comparisons->name,
130:                     fewest_comparisons->compare_count))}));
131: 
132:     Elements table_rows{
133:         text("Algorithm        Matches    Comparisons      Time(ms)") | heading_text(),
134:         separator() | color(catppuccin_mocha.surface1)
135:     };
136:     for (const AlgoResult& metric : metrics) {
137:         table_rows.push_back(text(std::format("{:<14} {:>8} {:>16} {:>13}",
138:             metric.name,
139:             metric.match_count,
140:             metric.compare_count,
