145: 
146:     auto bar = [](long long value, long long max_value) {
147:         constexpr int bar_width = 24;
148:         const int filled = max_value == 0 ? 0 : static_cast<int>((value * bar_width) / max_value);
149:         return std::format("{}{}", std::string(filled, '#'), std::string(bar_width - filled, '-'));
150:     };
151: 
152:     Elements visual_rows;
153:     for (const AlgoResult& metric : metrics) {
154:         visual_rows.push_back(text(metric.name) | heading_text());
155:         visual_rows.push_back(text(std::format("  Comparisons [{}] {}",
156:             bar(static_cast<long long>(metric.compare_count),
157:                 static_cast<long long>(max_comparisons)),
158:             metric.compare_count)));
159:         visual_rows.push_back(text(std::format(
160:             "  Time(ms)    [{}] {}", bar(metric.use_time_ms, max_time), metric.use_time_ms)));
161:     }
162:     auto visual_comparison =
