164: 
165:     return vbox(
166:                {summary,
167:                    separator() | color(catppuccin_mocha.surface1),
168:                    metrics_table,
169:                    separator() | color(catppuccin_mocha.surface1),
170:                    visual_comparison}) |
171:            frame | flex | color(catppuccin_mocha.text);
