186:     // NOTE: Top Bar
187:     // NOTE: Add Button & Add Book Modal
188:     ModalCon add_con;
189:     ModalCon error_con;
190:     std::string error_message;
191:     auto file_buttons = Container::Vertical({});
192:     auto add_fn = [&add_con, &error_con, &error_message, &file_buttons]() {
