234:     ModalCon mode_con;
235:     auto change_buttons = Container::Vertical({});
236:     for (const auto& mode : ::modes) {
237:         auto change_fn = [mode, &mode_con, &tab_con]() {
238:             if (mode == "compare") {
239:                 const std::string source = app_state.searchengine.get_loaded_text();
240:                 app_state.compare_metrics = make_compare_metrics(source, app_state.input);
