250:     }
251:     auto mode_fn = [&mode_con]() { mode_con.open(); };
252:     auto mode_button = rounded_button("Mode", mode_fn);
253:     auto mode_modal = Renderer(change_buttons, [&] {
254:         return hbox(
255:                    {text("Choose Mode") | heading_text() | center,
256:                        separator() | color(catppuccin_mocha.surface1),
257:                        change_buttons->Render()}) |
258:                themed_border() | color(catppuccin_mocha.text);
259:     });
