261:     // NOTE: Menu & Detail
262:     MenuCon menu_con{};
263:     MenuOption menu_option;
264:     menu_option.entries = &menu_con.entry;
265:     menu_option.selected = &menu_con.idx;
266:     menu_option.entries_option.transform = [](const EntryState& state) {
267:         auto element = text(state.label);
268:         if (state.active) {
269:             element |= color(catppuccin_mocha.lavender) | bold;
270:         } else {
271:             element |= color(catppuccin_mocha.text);
