328:     auto top_bar_eles = Container::Horizontal(
329:         {add_button, mode_button, search_input, distance_input_con, search_button});
330:     auto top_bar = Renderer(top_bar_eles, [&]() {
331:         return hbox(
332:             {add_button->Render(),
333:                 mode_button->Render(),
334:                 search_input->Render() | borderStyled(ROUNDED, catppuccin_mocha.lavender),
335:                 distance_input_con->Render(),
336:                 search_button->Render()});
337:     });
338: 
339:     // NOTE: Body
340:     auto body_eles = Container::Horizontal({menu});
341:     auto body = Renderer(body_eles, [&] {
342:         if (tab_con.idx == 1) {
343:             return compare_pane(app_state.compare_metrics);
344:         }
345: 
346:         const int screen_width = screen.dimx() > 3 ? screen.dimx() : Terminal::Size().dimx;
347:         const int body_width = std::max(2, screen_width);
348:         const int menu_width = std::max(1, body_width / 3);
349:         const int detail_width = std::max(1, body_width - menu_width);
350: 
351:         Element detail = emptyElement();
352:         Element menu_view;
353:         if (!search_has_run) {
354:             menu_view = emptyElement() | frame | themed_border() | flex;
355:             detail =
356:                 vbox({
357:                     text("Search results will appear here") | heading_text() | center,
358:                     text("Enter a query above and press Search to begin") | muted_text() | center,
359:                 }) |
360:                 themed_border() | frame | flex;
361:         } else if (app_state.search_res.empty()) {
362:             menu_view = emptyElement() | frame | themed_border() | flex;
363:             detail = vbox({
364:                          text("No results found") | heading_text() | center,
365:                          separator() | color(catppuccin_mocha.surface1),
366:                          text("Try a different query or search mode") | muted_text() | center,
367:                      }) |
368:                      themed_border() | frame | flex;
369:         } else {
370:             menu_view = menu->Render() | vscroll_indicator | frame | themed_border() | flex |
371:                         reflect(menu_box);
372:         }
373: 
374:         if (!app_state.search_res.empty() && menu_con.idx >= 0 &&
375:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size()) {
376:             detail = detail_pane(app_state.get_context(menu_con.idx)) |
377:                      focusPosition(0, detail_scroll) | vscroll_indicator | yframe |
378:                      themed_border() | color(catppuccin_mocha.text);
379:         }
380:         return hbox(
381:                    {menu_view | size(WIDTH, EQUAL, menu_width),
382:                        detail | size(WIDTH, EQUAL, detail_width) | reflect(detail_box)}) |
383:                reflect(body_box);
384:     });
385: 
386:     // NOTE: State Bar
387:     auto state_bar = Renderer([&] {
388:         const std::string mode = tab_con.idx == 1 ? "compare" : std::format("{}", app_state.mode);
389:         return hbox(
390:             {text(std::format("Loaded Book: {}", app_state.loaded_books.size())) |
391:                     color(catppuccin_mocha.subtext0),
392:                 emptyElement() | flex,
393:                 text(std::format("Search Count:{}", app_state.search_res.size())) |
394:                     color(catppuccin_mocha.subtext0),
395:                 emptyElement() | flex,
396:                 text(std::format("Mode:{}", mode)) | color(catppuccin_mocha.lavender)});
397:     });
398: 
399:     auto main_eles = Container::Vertical({top_bar, body, state_bar});
400:     auto main_renderer = Renderer(main_eles, [&] {
401:         return vbox({top_bar->Render(), body->Render() | flex, state_bar->Render()}) |
402:                color(catppuccin_mocha.text);
403:     });
404: 
405:     main_renderer |= Modal(add_modal, &add_con.is_open);
406:     main_renderer |= Modal(mode_modal, &mode_con.is_open);
407:     main_renderer |= Modal(error_modal, &error_con.is_open);
408:     main_renderer |= CatchEvent([&](Event event) {
409:         if (event == Event::Escape && error_con.is_open) {
410:             error_con.close();
411:             return true;
412:         }
413:         if (event == Event::Escape && add_con.is_open) {
414:             add_con.close();
415:             return true;
416:         }
417:         if (event == Event::Escape && mode_con.is_open) {
418:             mode_con.close();
419:             return true;
420:         }
421: 
422:         const bool can_scroll_detail =
423:             !add_con.is_open && !mode_con.is_open && !error_con.is_open && tab_con.idx == 0 &&
424:             !app_state.search_res.empty() && menu_con.idx >= 0 &&
425:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size();
426:         if (!can_scroll_detail) {
427:             return false;
428:         }
429: 
430:         auto scroll_detail = [&](int delta) {
431:             detail_scroll = std::max(0, detail_scroll + delta);
432:             return true;
433:         };
434:         auto is_in_box = [](const Box& box, int x, int y) {
435:             return x >= box.x_min && x <= box.x_max && y >= box.y_min && y <= box.y_max;
436:         };
437:         auto is_in_detail_area = [&](int x, int y) {
438:             if (is_in_box(menu_box, x, y)) {
439:                 return false;
440:             }
441:             if (is_in_box(detail_box, x, y)) {
442:                 return true;
443:             }
444:             return is_in_box(body_box, x, y) && x > menu_box.x_max;
445:         };
446: 
447:         if (event == Event::PageUp) {
448:             return scroll_detail(-8);
449:         }
450:         if (event == Event::PageDown) {
451:             return scroll_detail(8);
452:         }
453:         if (event == Event::ArrowUpCtrl) {
454:             return scroll_detail(-1);
455:         }
456:         if (event == Event::ArrowDownCtrl) {
457:             return scroll_detail(1);
458:         }
459:         if (event.is_mouse() &&
460:             (event.mouse().button == Mouse::WheelUp || event.mouse().button == Mouse::WheelDown)) {
461:             if (!is_in_detail_area(event.mouse().x, event.mouse().y)) {
462:                 return false;
463:             }
464:             return scroll_detail(event.mouse().button == Mouse::WheelUp ? -3 : 3);
465:         }
466:         return false;
467:     });
468: 
469:     screen.Loop(main_renderer);
470: }

