80: std::string get_filename(std::string_view path) {
81:     const std::size_t pos = path.find_last_of("/\\");
82: 
83:     if (pos == std::string_view::npos) {
84:         return std::string(path);
85:     }
86: 
87:     return std::string(path.substr(pos + 1));
