90: size_t parse_near_distance(std::string_view value) {
91:     size_t distance = default_near_distance;
92:     const char* begin = value.data();
93:     const char* end = begin + value.size();
94:     const auto [ptr, ec] = std::from_chars(begin, end, distance);
95: 
96:     if (ec != std::errc{} || ptr != end) {
97:         return default_near_distance;
98:     }
99: 
100:     return distance;
101: }
