132: ftxui::Element compare_pane(const AlgoResults& metrics) {
133:     using namespace ftxui;
134: 
135:     const auto fastest = std::ranges::min_element(metrics, {}, &AlgoResult::use_time_ms);
136:     const auto fewest_comparisons =
137:         std::ranges::min_element(metrics, {}, &AlgoResult::compare_count);
138:     const auto max_comparisons =
139:         std::ranges::max(metrics | std::views::transform(&AlgoResult::compare_count));
140:     const auto max_time =
141:         std::ranges::max(metrics | std::views::transform(&AlgoResult::use_time_ms));
142: 
143:     auto summary =
144:         vbox(
145:             {text(" Compare Summary ") | heading_text() | center,
146:                 separator() | color(catppuccin_mocha.overlay0),
147:                 text(std::format(
148:                     "Fastest algorithm: {} ({} ms)", fastest->name, fastest->use_time_ms)),
149:                 text(std::format("Fewest comparisons: {} ({})",
150:                     fewest_comparisons->name,
151:                     fewest_comparisons->compare_count))}) |
152:         themed_border(catppuccin_mocha.mauve);
153: 
154:     Elements table_rows{
155:         text("Algorithm        Matches    Comparisons      Time(ms)") | heading_text(),
156:         separator() | color(catppuccin_mocha.overlay0)
157:     };
158:     for (const AlgoResult& metric : metrics) {
159:         table_rows.push_back(text(std::format("{:<14} {:>8} {:>16} {:>13}",
160:             metric.name,
161:             metric.match_count,
162:             metric.compare_count,
163:             metric.use_time_ms)));
164:     }
165:     auto metrics_table = vbox(
166:                              {text(" Metrics Table ") | heading_text() | center,
167:                                  separator() | color(catppuccin_mocha.overlay0),
168:                                  vbox(std::move(table_rows))}) |
169:                          themed_border(catppuccin_mocha.green);
170: 
171:     auto bar = [](long long value, long long max_value) {
172:         constexpr int bar_width = 24;
173:         const int filled = max_value == 0 ? 0 : static_cast<int>((value * bar_width) / max_value);
174:         return std::format("{}{}", std::string(filled, '#'), std::string(bar_width - filled, '-'));
175:     };
176: 
177:     Elements visual_rows;
178:     for (const AlgoResult& metric : metrics) {
179:         visual_rows.push_back(text(metric.name) | heading_text());
180:         visual_rows.push_back(text(std::format("  Comparisons [{}] {}",
181:             bar(static_cast<long long>(metric.compare_count),
182:                 static_cast<long long>(max_comparisons)),
183:             metric.compare_count)));
184:         visual_rows.push_back(text(std::format(
185:             "  Time(ms)    [{}] {}", bar(metric.use_time_ms, max_time), metric.use_time_ms)));
186:     }
187:     auto visual_comparison = vbox(
188:                                  {text(" Visual Comparison ") | heading_text() | center,
189:                                      separator() | color(catppuccin_mocha.overlay0),
190:                                      vbox(std::move(visual_rows))}) |
191:                              themed_border(catppuccin_mocha.blue);
192: 
193:     return vbox(
194:                {summary,
195:                    separator() | color(catppuccin_mocha.overlay0),
196:                    metrics_table,
197:                    separator() | color(catppuccin_mocha.overlay0),
198:                    visual_comparison}) |
199:            frame | flex | color(catppuccin_mocha.text);
200: }
