295:         };
296:         change_buttons->Add(rounded_button(mode, change_fn, catppuccin_mocha.maroon));
297:     }
298:     auto mode_fn = [&mode_con]() { mode_con.open(); };
299:     auto mode_button = rounded_button("Mode", mode_fn, catppuccin_mocha.maroon);
300:     auto mode_modal = Renderer(change_buttons, [&] {
301:         return vbox(
302:                    {text("Choose Mode") | heading_text() | center,
303:                        separator() | color(catppuccin_mocha.maroon),
304:                        change_buttons->Render() | center}) |
305:                themed_border(catppuccin_mocha.maroon) | color(catppuccin_mocha.text);
306:     });
307: 
308:     // NOTE: Menu & Detail
309:     MenuCon menu_con{};
310:     MenuOption menu_option;
311:     menu_option.entries = &menu_con.entry;
312:     menu_option.selected = &menu_con.idx;
313:     menu_option.entries_option.transform = [](const EntryState& state) {
314:         auto element = text(state.label);
315:         if (state.active) {
316:             element |= color(catppuccin_mocha.blue) | bgcolor(catppuccin_mocha.surface1) | bold;
317:         } else {
318:             element |= color(catppuccin_mocha.blue);
319:         }
320:         if (state.focused) {
321:             element |= color(catppuccin_mocha.blue) | bgcolor(catppuccin_mocha.surface1) | bold;
322:         }
323:         return element;
324:     };
325:     auto menu = Menu(menu_option);
326:     Box menu_box;
327:     Box detail_box;
328:     Box body_box;
329: 
330:     // NOTE: search button
331:     auto search = [&menu_con, &tab_con, &detail_scroll, &compare_scroll, &search_has_run] {
332:         if (tab_con.idx == 1) {
333:             const std::string source = app_state.searchengine.get_loaded_text();
334:             app_state.compare_metrics = make_compare_metrics(source, app_state.input);
335:             compare_scroll = 0;
336:             return;
337:         }
338: 
339:         SearchRequest request{
340:             .mode = app_state.mode,
341:             .query = app_state.input,
342:             .near_distance = parse_near_distance(app_state.near_distance),
343:         };
344:         app_state.search_res = app_state.searchengine.search_with_context(request);
345:         menu_con.entry = app_state.search_res | std::views::transform([](const Index& ele) {
346:             return std::format("{}", ele);
347:         }) | std::ranges::to<std::vector<std::string>>();
348:         menu_con.idx = 0;
349:         detail_scroll = 0;
350:         search_has_run = true;
351:     };
352:     auto search_button = rounded_button("", search, catppuccin_mocha.pink);
353: 
354:     // NOTE: Input
355:     auto get_input = [&search](std::string& content, ftxui::Color input_color) {
356:         InputOption option;
357:         option.multiline = false;
358:         option.on_enter = search;
359:         option.transform = [input_color](InputState state) {
360:             auto element = state.element | color(input_color);
361:             if (state.is_placeholder) {
362:                 element |= color(catppuccin_mocha.overlay0);
363:             }
364:             return element;
365:         };
366:         return Input(&content, option);
367:     };
368:     auto search_input = get_input(app_state.input, catppuccin_mocha.pink);
369:     auto distance_input = get_input(app_state.near_distance, catppuccin_mocha.text);
370:     auto distance_input_con = Renderer(distance_input, [&] {
371:         return hbox(
372:             {text(" Dist:") | color(catppuccin_mocha.subtext0),
373:                 distance_input->Render() | borderStyled(ROUNDED, catppuccin_mocha.overlay0)});
374:     }) | Maybe([] { return app_state.mode == SearchMode::Near; });
375: 
376:     auto top_bar_eles = Container::Horizontal(
377:         {add_button, mode_button, search_input, distance_input_con, search_button});
378:     auto top_bar = Renderer(top_bar_eles, [&]() {
379:         return hbox(
380:             {add_button->Render(),
381:                 mode_button->Render(),
382:                 search_input->Render() | borderStyled(ROUNDED, catppuccin_mocha.pink),
383:                 distance_input_con->Render(),
384:                 search_button->Render()});
385:     });
386: 
387:     // NOTE: Body
388:     auto body_eles = Container::Horizontal({menu});
389:     auto body = Renderer(body_eles, [&] {
390:         if (tab_con.idx == 1) {
391:             return compare_pane(app_state.compare_metrics) | focusPosition(0, compare_scroll) |
392:                    vscroll_indicator | yframe | flex | reflect(body_box);
393:         }
394: 
395:         const int screen_width = screen.dimx() > 3 ? screen.dimx() : Terminal::Size().dimx;
396:         const int body_width = std::max(2, screen_width);
397:         const int menu_width = std::max(1, body_width / 3);
398:         const int detail_width = std::max(1, body_width - menu_width);
399: 
400:         Element detail = emptyElement();
401:         Element menu_view;
402:         if (!search_has_run) {
403:             menu_view = emptyElement() | frame | themed_border(catppuccin_mocha.blue) | flex;
404:             detail =
405:                 vbox({
406:                     text("Search results will appear here") | heading_text() | center,
407:                     text("Enter a query above and press Search to begin") | muted_text() | center,
408:                 }) |
409:                 themed_border(catppuccin_mocha.mauve) | frame | flex;
410:         } else if (app_state.search_res.empty()) {
411:             menu_view = emptyElement() | frame | themed_border(catppuccin_mocha.blue) | flex;
412:             detail = vbox({
413:                          text("No results found") | heading_text() | center,
414:                          separator() | color(catppuccin_mocha.mauve),
415:                          text("Try a different query or search mode") | muted_text() | center,
416:                      }) |
417:                      themed_border(catppuccin_mocha.mauve) | frame | flex;
418:         } else {
419:             menu_view = menu->Render() | vscroll_indicator | frame |
420:                         themed_border(catppuccin_mocha.blue) | flex | reflect(menu_box);
421:         }
422: 
423:         if (!app_state.search_res.empty() && menu_con.idx >= 0 &&
424:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size()) {
425:             detail = detail_pane(app_state.get_context(menu_con.idx)) |
426:                      focusPosition(0, detail_scroll) | vscroll_indicator | yframe |
427:                      themed_border(catppuccin_mocha.mauve) | color(catppuccin_mocha.text);
428:         }
429:         return hbox(
430:                    {menu_view | size(WIDTH, EQUAL, menu_width),
431:                        detail | size(WIDTH, EQUAL, detail_width) | reflect(detail_box)}) |
432:                reflect(body_box);
433:     });
434: 
435:     // NOTE: State Bar
436:     auto state_bar = Renderer([&] {
437:         const std::string mode = tab_con.idx == 1 ? "compare" : std::format("{}", app_state.mode);
438:         Elements items{
439:             text(std::format("Books:{}", app_state.loaded_books.size())) |
440:                 color(catppuccin_mocha.subtext0),
441:             emptyElement() | flex,
442:             text(std::format("Mode:{}", mode)) | color(catppuccin_mocha.blue),
443:             emptyElement() | flex,
444:         };
445: 
446:         const std::string query = app_state.input.empty() ? "<empty>" : app_state.input;
447:         if (tab_con.idx == 1) {
448:             items.push_back(text(std::format("Target:{}", query)) | color(catppuccin_mocha.pink));
449:             items.push_back(emptyElement() | flex);
450:             items.push_back(text(std::format("Algorithms:{}", app_state.compare_metrics.size())) |
451:                             color(catppuccin_mocha.green));
452:             return hbox(std::move(items));
453:         }
454: 
455:         if (app_state.mode == SearchMode::Near) {
456:             items.push_back(text(std::format("Dist:{}", parse_near_distance(app_state.near_distance))) |
457:                             color(catppuccin_mocha.subtext0));
458:             items.push_back(emptyElement() | flex);
459:         }
460: 
461:         if (!app_state.input.empty()) {
462:             items.push_back(text(std::format("Query:{}", app_state.input)) | color(catppuccin_mocha.pink));
463:             items.push_back(emptyElement() | flex);
464:         }
465: 
466:         if (!search_has_run) {
467:             items.push_back(text("Ready") | color(catppuccin_mocha.teal));
468:         } else if (app_state.search_res.empty()) {
469:             items.push_back(text("No Results") | color(catppuccin_mocha.red));
470:         } else {
471:             items.push_back(text(std::format(
472:                                 "Result:{}/{}", menu_con.idx + 1, app_state.search_res.size())) |
473:                             color(catppuccin_mocha.green));
474:         }
475:         return hbox(std::move(items));
476:     });
477: 
478:     auto main_eles = Container::Vertical({top_bar, body, state_bar});
479:     auto main_renderer = Renderer(main_eles,
480:         [&] { return vbox({top_bar->Render(), body->Render() | flex, state_bar->Render()}); });
481: 
482:     main_renderer |= Modal(add_modal, &add_con.is_open);
483:     main_renderer |= Modal(mode_modal, &mode_con.is_open);
484:     main_renderer |= Modal(error_modal, &error_con.is_open);
485:     main_renderer |= CatchEvent([&](Event event) {
486:         if (event == Event::Escape && error_con.is_open) {
487:             error_con.close();
488:             return true;
489:         }
490:         if (event == Event::Escape && add_con.is_open) {
491:             add_con.close();
492:             return true;
493:         }
494:         if (event == Event::Escape && mode_con.is_open) {
495:             mode_con.close();
496:             return true;
497:         }
498: 
499:         const bool can_scroll = !add_con.is_open && !mode_con.is_open && !error_con.is_open;
500:         if (!can_scroll) {
501:             return false;
502:         }
503: 
504:         auto is_in_box = [](const Box& box, int x, int y) {
505:             return x >= box.x_min && x <= box.x_max && y >= box.y_min && y <= box.y_max;
506:         };
507: 
508:         auto scroll_compare = [&](int delta) {
509:             compare_scroll = std::max(0, compare_scroll + delta);
510:             return true;
511:         };
512:         if (tab_con.idx == 1) {
513:             if (event == Event::PageUp) {
514:                 return scroll_compare(-8);
515:             }
516:             if (event == Event::PageDown) {
517:                 return scroll_compare(8);
518:             }
519:             if (event == Event::ArrowUpCtrl) {
520:                 return scroll_compare(-1);
521:             }
522:             if (event == Event::ArrowDownCtrl) {
523:                 return scroll_compare(1);
524:             }
525:             if (event.is_mouse() && (event.mouse().button == Mouse::WheelUp ||
526:                                         event.mouse().button == Mouse::WheelDown)) {
527:                 return scroll_compare(event.mouse().button == Mouse::WheelUp ? -3 : 3);
528:             }
529:             return false;
530:         }
531: 
532:         const bool can_scroll_detail =
533:             tab_con.idx == 0 && !app_state.search_res.empty() && menu_con.idx >= 0 &&
534:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size();
535:         if (!can_scroll_detail) {
536:             return false;
537:         }
538: 
539:         auto scroll_detail = [&](int delta) {
540:             detail_scroll = std::max(0, detail_scroll + delta);
541:             return true;
542:         };
543:         auto is_in_detail_area = [&](int x, int y) {
544:             if (is_in_box(menu_box, x, y)) {
545:                 return false;
546:             }
547:             if (is_in_box(detail_box, x, y)) {
548:                 return true;
549:             }
550:             return is_in_box(body_box, x, y) && x > menu_box.x_max;
551:         };
552: 
553:         if (event == Event::PageUp) {
554:             return scroll_detail(-8);
555:         }
556:         if (event == Event::PageDown) {
557:             return scroll_detail(8);
558:         }
559:         if (event == Event::ArrowUpCtrl) {
560:             return scroll_detail(-1);
561:         }
562:         if (event == Event::ArrowDownCtrl) {
563:             return scroll_detail(1);
564:         }
565:         if (event.is_mouse() &&
566:             (event.mouse().button == Mouse::WheelUp || event.mouse().button == Mouse::WheelDown)) {
567:             if (!is_in_detail_area(event.mouse().x, event.mouse().y)) {
568:                 return false;
569:             }
570:             return scroll_detail(event.mouse().button == Mouse::WheelUp ? -3 : 3);
571:         }
572:         return false;
573:     });
574: 
575:     screen.Loop(main_renderer);
576: }

