+                text(std::format("Fewest comparisons: {} ({})",
+                    fewest_comparisons->name,
+                    fewest_comparisons->compare_count))}) |
+        themed_border(catppuccin_mocha.mauve);
+
+    Elements table_rows{
+        text("Algorithm        Matches    Comparisons      Time(ms)") |
+            heading_text(catppuccin_mocha.green),
+        separator() | color(catppuccin_mocha.green)
+    };
+    for (const AlgoResult& metric : metrics) {
+        table_rows.push_back(text(std::format("{:<14} {:>8} {:>16} {:>13}",
+            metric.name,
+            metric.match_count,
+            metric.compare_count,
+            metric.use_time_ms)));
+    }
+    auto metrics_table =
+        vbox(
+            {text(" Metrics Table ") | heading_text(catppuccin_mocha.green) | center,
+                separator() | color(catppuccin_mocha.green),
+                vbox(std::move(table_rows))}) |
+        themed_border(catppuccin_mocha.green);
+
+    auto percent = [](long long value, long long max_value) {
+        return max_value == 0 ? 0 : static_cast<int>((value * 100) / max_value);
+    };
+    auto bar = [](long long value, long long max_value) {
+        constexpr int bar_width = 24;
+        const int filled = max_value == 0 ? 0 : static_cast<int>((value * bar_width) / max_value);
+        std::string result;
+        result.reserve(static_cast<size_t>(bar_width) * 3);
+        for (int i = 0; i < bar_width; ++i) {
+            result += i < filled ? "█" : "░";
+        }
+        return result;
+    };
+
+    Elements visual_rows;
