+                vbox(std::move(visual_rows))}) |
+        themed_border(catppuccin_mocha.blue);
+
+    return vbox({summary, metrics_table, visual_comparison}) | frame | flex |
+           color(catppuccin_mocha.text);
+}
+
+}
