211:         const int screen_width = screen.dimx() > 3 ? screen.dimx() : Terminal::Size().dimx;
212:         const int body_width = std::max(2, screen_width);
213:         const int menu_width = std::max(1, body_width / 3);
214:         const int detail_width = std::max(1, body_width - menu_width);
215: 
216:         Element detail = emptyElement();
217:         Element menu_view;
218:         if (!search_has_run) {
219:             menu_view = emptyElement() | frame | themed_border(catppuccin_mocha.blue) | flex;
220:             detail =
221:                 vbox({
222:                     text("Search results will appear here") | heading_text() | center,
223:                     text("Enter a query above and press Search to begin") | muted_text() | center,
224:                 }) |
225:                 themed_border(catppuccin_mocha.mauve) | frame | flex;
226:         } else if (app_state.search_res.empty()) {
227:             menu_view = emptyElement() | frame | themed_border(catppuccin_mocha.blue) | flex;
228:             detail = vbox({
229:                          text("No results found") | heading_text() | center,
230:                          separator() | color(catppuccin_mocha.mauve),
231:                          text("Try a different query or search mode") | muted_text() | center,
232:                      }) |
233:                      themed_border(catppuccin_mocha.mauve) | frame | flex;
234:         } else {
