236:                         themed_border(catppuccin_mocha.blue) | flex | reflect(menu_box);
237:         }
238: 
239:         if (!app_state.search_res.empty() && menu_con.idx >= 0 &&
240:             static_cast<size_t>(menu_con.idx) < app_state.search_res.size()) {
241:             detail = detail_pane(app_state.get_context(menu_con.idx)) |
