246:                    {menu_view | size(WIDTH, EQUAL, menu_width),
247:                        detail | size(WIDTH, EQUAL, detail_width) | reflect(detail_box)}) |
248:                reflect(body_box);
249:     });
250: 
251:     // NOTE: State Bar
252:     auto state_bar = Renderer([&] {
253:         const std::string mode = tab_con.idx == 1 ? "compare" : std::format("{}", app_state.mode);
